import GUI from './vendor/lil-gui.esm.min.js';
import {readTuning,applyTuning,validateTuning,TUNING_BOUNDS} from './tuning-model.js?v=fx-260';
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
export async function createDeveloperTools(hooks){
 if(!window.Stats)await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='vendor/stats.min.js';script.onload=resolve;script.onerror=()=>reject(Error('Performance monitor failed to load'));document.head.append(script);});
 const defaults=readTuning(),values={...defaults},gui=new GUI({title:"Light's End · Local playtest",width:305}),stats=new window.Stats(),monitor={enabled:false,samples:[],elapsed:0};gui.domElement.id='developer-tools';gui.domElement.style.cssText+=';position:fixed;left:14px;right:auto;top:78px;max-height:70vh;overflow:auto;z-index:50';stats.dom.id='performance-stats';stats.dom.style.cssText='position:fixed;left:14px;top:8px;z-index:51;display:none';document.body.append(stats.dom);
 const note=document.createElement('p');note.textContent='Local experiments only. Export settings to keep them; Reset restores this build.';note.style.cssText='font:11px/1.5 sans-serif;padding:8px;margin:0;color:#ead6ac';gui.domElement.append(note);
 const perf=document.createElement('pre');perf.id='performance-details';perf.style.cssText='display:none;position:fixed;left:110px;top:8px;z-index:51;background:#14201ee8;color:#daf0d9;padding:6px 9px;margin:0;font:10px/1.6 monospace;pointer-events:none';document.body.append(perf);
 const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.hidden=true;document.body.append(input);
 const update=()=>{try{applyTuning(values,hooks.targets());hooks.changed?.();}catch(e){hooks.notice(e.message);}};
 const add=(folder,key,name,step)=>folder.add(values,key,...TUNING_BOUNDS[key],step).name(name).onChange(update);
 const enemies=gui.addFolder('Enemy movement');for(const [key,name] of [['swarmer','Basic mobs'],['bruiser','Heavy mobs'],['leader','Elites'],['boss','Mini-boss']])add(enemies,key,name,1);
 const elite=gui.addFolder('Elite melee');add(elite,'eliteReach','Reach',1);add(elite,'eliteWindup','Windup seconds',.01);add(elite,'eliteRecovery','Recovery seconds',.01);
 const pressure=gui.addFolder('Spawn pressure');add(pressure,'spawnRate','Arrival multiplier',.05);add(pressure,'population','Population multiplier',.05);
 const basics=gui.addFolder('Reference basic attacks');add(basics,'swordDamage','Longsword damage',1);add(basics,'orbDamage','Orb damage',1);
 const options={pause:()=>hooks.pause?.(),performance:false,reset:()=>{Object.assign(values,defaults);update();gui.controllersRecursive().forEach(c=>c.updateDisplay());hooks.notice('Build defaults restored');},export:()=>download('veyrath-tuning.json',{schema:1,values:readTuning()}),import:()=>input.click(),close:()=>gui.hide()};
 gui.add(options,'pause').name('Pause / resume simulation');
 gui.add(options,'performance').name('Performance overlay').onChange(on=>{monitor.enabled=on;monitor.samples=[];stats.dom.style.display=on?'block':'none';perf.style.display=on?'block':'none';});
 gui.add(options,'reset').name('Reset tuning to build defaults');gui.add(options,'export').name('Export tuning JSON');gui.add(options,'import').name('Import tuning JSON');gui.add(options,'close').name('Close developer panel');
 input.onchange=async()=>{const file=input.files[0];input.value='';if(!file)return;try{if(file.size>20000)throw Error('Tuning file is too large');const parsed=validateTuning(JSON.parse(await file.text()));applyTuning(parsed,hooks.targets());Object.assign(values,parsed);gui.controllersRecursive().forEach(c=>c.updateDisplay());hooks.changed?.();hooks.notice('Local tuning imported');}catch(e){hooks.notice('Import cancelled: '+e.message);}};
 return {show(){gui.show();},monitor,frame({elapsed,updateMs,renderMs,counts}){if(!monitor.enabled||document.hidden)return;stats.update();monitor.samples.push({frame:elapsed*1000,update:updateMs,render:renderMs});if(monitor.samples.length>120)monitor.samples.shift();monitor.elapsed+=elapsed;if(monitor.elapsed<.5)return;monitor.elapsed=0;const arr=monitor.samples,avg=key=>arr.reduce((n,a)=>n+a[key],0)/arr.length,ordered=arr.map(a=>a.frame).sort((a,b)=>a-b),p95=ordered[Math.floor((ordered.length-1)*.95)];perf.textContent='Update '+avg('update').toFixed(1)+'ms | Draw '+avg('render').toFixed(1)+'ms | p95 frame '+p95.toFixed(1)+'ms\n'+counts+'\n'+(hooks.mapStatus?.()??'');}};
}
